import{_ as p,a0 as o,w as d,s as r,ao as l,I as a,x as n,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"在 Linux 上使用 NTP 保持精確的時間 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上使用 NTP 保持精確的時間 | LCTT (201803) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上使用 NTP 保持精確的時間 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上使用 NTP 保持精確的時間 | LCTT (201803) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201803/20180125 Keep Accurate Time on Linux with NTP","title":"在 Linux 上使用 NTP 保持精確的時間","tag":"201803","desc":""},"relativePath":"201803/20180125 Keep Accurate Time on Linux with NTP.md","filePath":"[post].md"}'),c={name:"201803/20180125 Keep Accurate Time on Linux with NTP.md"};function u(g,s,h,k,m,T){const e=o("Link");return d(),r("div",null,[s[30]||(s[30]=l(`<h1 id="在-linux-上使用-ntp-保持精確的時間" tabindex="-1">在 Linux 上使用 NTP 保持精確的時間 <a class="header-anchor" href="#在-linux-上使用-ntp-保持精確的時間" aria-label="Permalink to “在 Linux 上使用 NTP 保持精確的時間”">​</a></h1><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/usno-amc.jpg?itok=KA8HwI02" alt=""></p><p>如何保持正確的時間，如何使用 NTP 和 systemd 讓你的計算機在不濫用時間服務器的前提下保持同步。</p><h3 id="它的時間是多少" tabindex="-1">它的時間是多少？ <a class="header-anchor" href="#它的時間是多少" aria-label="Permalink to “它的時間是多少？”">​</a></h3><p>讓 Linux 來告訴你時間的時候，它是很奇怪的。你可能認為是使用 <code>time</code> 命令來告訴你時間，其實並不是，因為 <code>time</code> 只是一個測量一個進程運行了多少時間的計時器。為得到時間，你需要運行的是 <code>date</code> 命令，你想查看更多的日期，你可以運行 <code>cal</code> 命令。文件上的時間戳也是一個容易混淆的地方，因為根據你的發行版默認情況不同，它一般有兩種不同的顯示方法。下面是來自 Ubuntu 16.04 LTS 的示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l</span></span>
<span class="line"><span>drwxrwxr-x 5 carla carla 4096 Mar 27 2017 stuff</span></span>
<span class="line"><span>drwxrwxr-x 2 carla carla 4096 Dec 8 11:32 things</span></span>
<span class="line"><span>-rw-rw-r-- 1 carla carla 626052 Nov 21 12:07 fatpdf.pdf</span></span>
<span class="line"><span>-rw-rw-r-- 1 carla carla 2781 Apr 18 2017 oddlots.txt</span></span></code></pre></div>`,6)),a("p",null,[s[1]||(s[1]=n("有些顯示年，有些顯示時間，這樣的方式讓你的文件更混亂。GNU 默認的情況是，如果你的文件在六個月以內，則顯示時間而不是年。我想這樣做可能是有原因的。如果你的 Linux 是這樣的，嘗試用 ",-1)),s[2]||(s[2]=a("code",null,"ls -l --time-style=long-iso",-1)),s[3]||(s[3]=n(" 命令，讓時間戳用同一種方式去顯示，按字母順序排序。請查閲 ",-1)),i(e,{href:"https://www.linux.com/learn/how-change-linux-date-and-time-simple-commands"},{default:t(()=>[...s[0]||(s[0]=[n("如何更改 Linux 的日期和時間：簡單的命令",-1)])]),_:1}),s[4]||(s[4]=n(" 去學習 Linux 上管理時間的各種方法。",-1))]),s[31]||(s[31]=l(`<h3 id="檢查當前設置" tabindex="-1">檢查當前設置 <a class="header-anchor" href="#檢查當前設置" aria-label="Permalink to “檢查當前設置”">​</a></h3><p>NTP —— 網絡時間協議，它是保持計算機正確時間的老式方法。<code>ntpd</code> 是 NTP 守護程序，它通過週期性地查詢公共時間服務器來按需調整你的計算機時間。它是一個簡單的、輕量級的協議，使用它的基本功能時設置非常容易。systemd 通過使用 <code>systemd-timesyncd.service</code> 已經越俎代庖地 “幹了 NTP 的活”，它可以用作 <code>ntpd</code> 的客户端。</p><p>在我們開始與 NTP “打交道” 之前，先花一些時間來了檢查一下當前的時間設置是否正確。</p><p>你的系統上（至少）有兩個時鐘：系統時間 —— 它由 Linux 內核管理，第二個是你的主板上的硬件時鐘，它也稱為實時時鐘（RTC）。當你進入系統的 BIOS 時，你可以看到你的硬件時鐘的時間，你也可以去改變它的設置。當你安裝一個新的 Linux 時，在一些圖形化的時間管理器中，你會被詢問是否設置你的 RTC 為 UTC（<ruby>世界標準時間<rt>Coordinated Universal Time</rt></ruby>）時區，因為所有的時區和夏令時都是基於 UTC 的。你可以使用 <code>hwclock</code> 命令去檢查：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo hwclock --debug</span></span>
<span class="line"><span>hwclock from util-linux 2.27.1</span></span>
<span class="line"><span>Using the /dev interface to the clock.</span></span>
<span class="line"><span>Hardware clock is on UTC time</span></span>
<span class="line"><span>Assuming hardware clock is kept in UTC time.</span></span>
<span class="line"><span>Waiting for clock tick...</span></span>
<span class="line"><span>...got clock tick</span></span>
<span class="line"><span>Time read from Hardware Clock: 2018/01/22 22:14:31</span></span>
<span class="line"><span>Hw clock time : 2018/01/22 22:14:31 = 1516659271 seconds since 1969</span></span>
<span class="line"><span>Time since last adjustment is 1516659271 seconds</span></span>
<span class="line"><span>Calculated Hardware Clock drift is 0.000000 seconds</span></span>
<span class="line"><span>Mon 22 Jan 2018 02:14:30 PM PST .202760 seconds</span></span></code></pre></div><p><code>Hardware clock is on UTC time</code> 表明了你的計算機的 RTC 是使用 UTC 時間的，雖然它把該時間轉換為你的本地時間。如果它被設置為本地時間，它將顯示 <code>Hardware clock is on local time</code>。</p><p>你應該有一個 <code>/etc/adjtime</code> 文件。如果沒有的話，使用如下命令同步你的 RTC 為系統時間，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo hwclock -w</span></span></code></pre></div><p>這個命令將生成該文件，內容看起來類似如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/adjtime</span></span>
<span class="line"><span>0.000000 1516661953 0.000000</span></span>
<span class="line"><span>1516661953</span></span>
<span class="line"><span>UTC</span></span></code></pre></div><p>新發明的 systemd 方式是去運行 <code>timedatectl</code> 命令，運行它不需要 root 權限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ timedatectl</span></span>
<span class="line"><span> Local time: Mon 2018-01-22 14:17:51 PST</span></span>
<span class="line"><span> Universal time: Mon 2018-01-22 22:17:51 UTC</span></span>
<span class="line"><span> RTC time: Mon 2018-01-22 22:17:51</span></span>
<span class="line"><span> Time zone: America/Los_Angeles (PST, -0800)</span></span>
<span class="line"><span> Network time on: yes</span></span>
<span class="line"><span>NTP synchronized: yes</span></span>
<span class="line"><span> RTC in local TZ: no</span></span></code></pre></div><p><code>RTC in local TZ: no</code> 表明它使用 UTC 時間。那麼怎麼改成使用本地時間？這裏有許多種方法可以做到。最簡單的方法是使用一個圖形配置工具，比如像 openSUSE 中的 YaST。你也可使用 <code>timedatectl</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ timedatectl set-local-rtc 0</span></span></code></pre></div><p>或者編輯 <code>/etc/adjtime</code>，將 <code>UTC</code> 替換為 <code>LOCAL</code>。</p><h3 id="systemd-timesyncd-客户端" tabindex="-1">systemd-timesyncd 客户端 <a class="header-anchor" href="#systemd-timesyncd-客户端" aria-label="Permalink to “systemd-timesyncd 客户端”">​</a></h3><p>現在，我已經累了，但是我們剛到非常精彩的部分。誰能想到計時如此複雜？我們甚至還沒有了解到它的皮毛；閲讀 <code>man 8 hwclock</code> 去了解你的計算機如何保持時間的詳細內容。</p><p>systemd 提供了 <code>systemd-timesyncd.service</code> 客户端，它可以查詢遠程時間服務器並調整你的本地系統時間。在 <code>/etc/systemd/timesyncd.conf</code> 中配置你的（時間）服務器。大多數 Linux 發行版都提供了一個默認配置，它指向他們維護的時間服務器上，比如，以下是 Fedora 的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Time]</span></span>
<span class="line"><span>#NTP=</span></span>
<span class="line"><span>#FallbackNTP=0.fedora.pool.ntp.org 1.fedora.pool.ntp.org</span></span></code></pre></div><p>你可以輸入你希望使用的其它時間服務器，比如你自己的本地 NTP 服務器，在 <code>NTP=</code> 行上輸入一個以空格分隔的服務器列表。（別忘了取消這一行的註釋）<code>NTP=</code> 行上的任何內容都將覆蓋掉 <code>FallbackNTP</code> 行上的配置項。</p><p>如果你不想使用 systemd 呢？那麼，你將需要 NTP 就行。</p><h3 id="配置-ntp-服務器和客户端" tabindex="-1">配置 NTP 服務器和客户端 <a class="header-anchor" href="#配置-ntp-服務器和客户端" aria-label="Permalink to “配置 NTP 服務器和客户端”">​</a></h3>`,22)),a("p",null,[s[6]||(s[6]=n("配置你自己的局域網 NTP 服務器是一個非常好的實踐，這樣你的網內計算機就不需要不停查詢公共 NTP 服務器。在大多數 Linux 上的 NTP 都來自 ",-1)),s[7]||(s[7]=a("code",null,"ntp",-1)),s[8]||(s[8]=n(" 包，它們大多都提供 ",-1)),s[9]||(s[9]=a("code",null,"/etc/ntp.conf",-1)),s[10]||(s[10]=n(" 文件去配置時間服務器。查閲 ",-1)),i(e,{href:"http://support.ntp.org/bin/view/Servers/NTPPoolServers"},{default:t(()=>[...s[5]||(s[5]=[n("NTP 時間服務器池",-1)])]),_:1}),s[11]||(s[11]=n(" 去找到你所在的區域的合適的 NTP 服務器池。然後在你的 ",-1)),s[12]||(s[12]=a("code",null,"/etc/ntp.conf",-1)),s[13]||(s[13]=n(" 中輸入 4 - 5 個服務器，每個服務器用單獨的一行：",-1))]),s[32]||(s[32]=l(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>driftfile /var/ntp.drift</span></span>
<span class="line"><span>logfile /var/log/ntp.log</span></span>
<span class="line"><span>server 0.europe.pool.ntp.org</span></span>
<span class="line"><span>server 1.europe.pool.ntp.org</span></span>
<span class="line"><span>server 2.europe.pool.ntp.org</span></span>
<span class="line"><span>server 3.europe.pool.ntp.org</span></span></code></pre></div><p><code>driftfile</code> 告訴 <code>ntpd</code> 它需要保存用於啓動時使用時間服務器快速同步你的系統時鐘的信息。而日誌也將保存在他們自己指定的目錄中，而不是轉儲到 syslog 中。如果你的 Linux 發行版默認提供了這些文件，請使用它們。</p><p>現在去啓動守護程序；在大多數主流的 Linux 中它的命令是 <code>sudo systemctl start ntpd</code>。讓它運行幾分鐘之後，我們再次去檢查它的狀態：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ntpq -p</span></span>
<span class="line"><span> remote refid st t when poll reach delay offset jitter</span></span>
<span class="line"><span>==============================================================</span></span>
<span class="line"><span>+dev.smatwebdesi 192.168.194.89 3 u 25 64 37 92.456 -6.395 18.530</span></span>
<span class="line"><span>*chl.la 127.67.113.92 2 u 23 64 37 75.175 8.820 8.230</span></span>
<span class="line"><span>+four0.fairy.mat 35.73.197.144 2 u 22 64 37 116.272 -10.033 40.151</span></span>
<span class="line"><span>-195.21.152.161 195.66.241.2 2 u 27 64 37 107.559 1.822 27.346</span></span></code></pre></div><p>我不知道這些內容是什麼意思，但重要的是，你的守護程序已經與時間服務器開始對話了，而這正是我們所需要的。你可以去運行 <code>sudo systemctl enable ntpd</code> 命令，永久啓用它。如果你的 Linux 沒有使用 systemd，那麼，給你留下的家庭作業就是找出如何去運行 <code>ntpd</code>。</p><p>現在，你可以在你的局域網中的其它計算機上設置 <code>systemd-timesyncd</code>，這樣它們就可以使用你的本地 NTP 服務器了，或者，在它們上面安裝 NTP，然後在它們的 <code>/etc/ntp.conf</code> 上輸入你的本地 NTP 服務器。</p><p>NTP 服務器會受到攻擊，而且需求在不斷增加。你可以通過運行你自己的公共 NTP 服務器來提供幫助。下週我們將學習如何運行你自己的公共服務器。</p>`,7)),a("p",null,[s[15]||(s[15]=n("通過來自 Linux 基金會和 edX 的免費課程 ",-1)),i(e,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:t(()=>[...s[14]||(s[14]=[n("“Linux 入門”",-1)])]),_:1}),s[16]||(s[16]=n(" 來學習更多 Linux 的知識。",-1))]),s[33]||(s[33]=a("hr",null,null,-1)),a("p",null,[s[18]||(s[18]=n("via: ",-1)),i(e,{href:"https://www.linux.com/learn/intro-to-linux/2018/1/keep-accurate-time-linux-ntp"},{default:t(()=>[...s[17]||(s[17]=[n("https://www.linux.com/learn/intro-to-linux/2018/1/keep-accurate-time-linux-ntp",-1)])]),_:1})]),a("p",null,[s[22]||(s[22]=n("作者：",-1)),i(e,{href:"https://www.linux.com/users/cschroder"},{default:t(()=>[...s[19]||(s[19]=[n("CARLA SCHRODER",-1)])]),_:1}),s[23]||(s[23]=n(" 譯者：",-1)),i(e,{href:"https://github.com/qhwdw"},{default:t(()=>[...s[20]||(s[20]=[n("qhwdw",-1)])]),_:1}),s[24]||(s[24]=n(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[21]||(s[21]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[27]||(s[27]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[25]||(s[25]=[n("LCTT",-1)])]),_:1}),s[28]||(s[28]=n(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[26]||(s[26]=[n("Linux中國",-1)])]),_:1}),s[29]||(s[29]=n(" 榮譽推出",-1))])])}const y=p(c,[["render",u]]);export{x as __pageData,y as default};
